402			t.Fatalf("replay recomputed: %+v vs %+v", first, replay)
403		}
404	
405		// 拒绝结果的重试：即使补登了版本也返回首次拒绝
406		rej, _ := b.Quote(QuoteRequest{RequestID: "rej", ItemID: "seat", VersionID: "ghost", Quantity: 1})
407		if rej.Confirmed || rej.Reason != ReasonVersionNotFound {
408			t.Fatalf("want not-found rejection: %+v", rej)
409		}
410		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "ghost", UnitPrice: 1, Start: at(10)}); err != nil {
411			t.Fatal(err)
412		}
413		rejReplay, err := b.Quote(QuoteRequest{RequestID: "rej", ItemID: "seat", VersionID: "ghost", Quantity: 1})
414		if err != nil {
415			t.Fatal(err)
416		}
417		if rejReplay != rej {
418			t.Fatalf("rejection replay recomputed: %+v vs %+v", rej, rejReplay)
419		}
420	
421		// 查询可分别得到确认记录与拒绝记录
422		if got, _ := b.Lookup("ok"); got != first {
423			t.Fatalf("lookup confirmed: %+v", got)
424		}
425		if got, _ := b.Lookup("rej"); got != rej {
426			t.Fatalf("lookup rejected: %+v", got)
427		}
428		if _, err := b.Lookup("never-seen"); !errors.Is(err, ErrRequestNotFound) {
429			t.Fatalf("unknown id: %v", err)
430		}
431	}
