502	// 登记成功后，调用方复用并改写原请求中的结束时间，不能影响账本。
503	func TestRegisterEndImmuneToRequestMutation(t *testing.T) {
504		now, setNow := fixedClock(at(0))
505		b := NewBook(WithClock(now))
506	
507		end := at(10)
508		req := RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: &end}
509		if err := b.RegisterVersion(req); err != nil {
510			t.Fatal(err)
511		}
512		// 旧版十点结束，新版十点开始（相邻交接）
513		if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(10)}); err != nil {
514			t.Fatal(err)
515		}
516	
517		// 把原请求中的结束时刻改晚到十二点
518		*req.End = at(12)
519		views, err := b.ItemVersions("seat")
520		if err != nil {
521			t.Fatal(err)
522		}
523		for _, v := range views {
524			if v.VersionID != "old" {
525				continue
526			}
527			if v.End == nil || !v.End.Equal(at(10)) {
528				t.Fatalf("registered end changed by request mutation: %v", v.End)
529			}
530			if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(10)) {
531				t.Fatalf("effective end changed by request mutation: %v", v.EffectiveEnd)
532			}
533		}
534		// 十一点旧版仍不可报价，新版可以——不能出现两版同时有效
535		setNow(at(11))
536		out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
537		if out.Confirmed || out.Reason != ReasonVersionExpired {
