539		}
540		out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "new", Quantity: 1})
541		if !out.Confirmed {
542			t.Fatalf("new version should be quotable at 11: %+v", out)
543		}
544	
545		// 改早到八点也不能让已登记版本提前到期
546		*req.End = at(8)
547		views, _ = b.ItemVersions("seat")
548		if views[0].End == nil || !views[0].End.Equal(at(10)) {
549			t.Fatalf("registered end moved earlier by request mutation: %v", views[0].End)
550		}
